//! Build-time OpenAPI contract generation.
//!
//! [`Contract`] is the state-less half of [`App`](crate::App): it resolves the same module tree
//! and builds the same OpenAPI document, but it only needs the application state *type*. No state
//! value is constructed and no router is assembled, so a contract can be generated by a build
//! script, a `cargo roundhouse` target or a test.
//!
//! [`BuiltContract::write_to`] writes the two artifacts the build-time workflow produces:
//!
//! - `contract.json` — route metadata and the request/response/validation facts the runtime
//!   consumes for validation and response verification;
//! - `openapi.json` — the OpenAPI 3.1 document.
//!
//! Under `build`, [`App::build`](crate::App::build) builds this contract in-process when no
//! bundle is supplied; under `contract` it consumes the committed bundle directly.

use std::any::TypeId;
use std::marker::PhantomData;
use std::path::Path;

use serde_json::{Map, Value, json};
use utoipa::openapi::Server;

use crate::build_error::{BuildError, Diagnostic};
use crate::doc::build::Observations;
use crate::doc::layer::LayerDoc;
use crate::openapi::{Info, OpenApi};
use crate::registry::{Module, ValidationPolicy};

use super::app::DocumentHook;
use super::build::{DocumentConfig, build_openapi};
use super::built::ResolvedRoute;
use super::fragment::{DocumentRejections, Fragment};
use super::resolve::resolve_tree;

/// A state-less OpenAPI contract builder.
///
/// The state type parameter is used only for the same state checks `App` performs. No value of
/// `S` is required (or constructed):
///
/// ```no_run
/// # use roundhouse::prelude::*;
/// # roundhouse::app_state!(());
/// # roundhouse::routes! {}
/// let contract = roundhouse::Contract::<()>::new(
///     roundhouse::openapi::Info::new("API", "0.1.0"),
/// )
/// .fragment(__roundhouse_fragment())
/// .build()
/// .expect("route declarations are consistent");
/// ```
pub struct Contract<S = ()> {
    info: Info,
    roots: Vec<&'static Module>,
    servers: Vec<Server>,
    document_hooks: Vec<DocumentHook>,
    layer_docs: Vec<fn() -> LayerDoc>,
    document_rejections: DocumentRejections,
    strict: bool,
    allow_undeclared_success: bool,
    response_defaults: std::collections::BTreeMap<u16, String>,
    registrations: Vec<fn(&mut dyn crate::doc::SchemaContext)>,
    _state: PhantomData<fn() -> S>,
}

impl<S: 'static> Contract<S> {
    /// Start a contract build for application state `S`.
    pub fn new(info: impl Into<Info>) -> Self {
        Self {
            info: info.into(),
            roots: Vec::new(),
            servers: Vec::new(),
            document_hooks: Vec::new(),
            layer_docs: Vec::new(),
            document_rejections: DocumentRejections::Auto,
            strict: true,
            allow_undeclared_success: false,
            response_defaults: std::collections::BTreeMap::new(),
            registrations: Vec::new(),
            _state: PhantomData,
        }
    }

    /// Root the contract at one module tree emitted by `routes!`.
    pub fn include(mut self, module: &'static Module) -> Self {
        self.roots.push(module);
        self
    }

    /// Root the contract at an explicit [`Fragment`].
    pub fn fragment(mut self, fragment: Fragment) -> Self {
        self.roots.extend(fragment.roots().iter().copied());
        self
    }

    /// Add one `servers` entry to the document.
    pub fn server(mut self, server: impl Into<Server>) -> Self {
        self.servers.push(server.into());
        self
    }

    /// Add several `servers` entries to the document.
    pub fn servers<I, T>(mut self, servers: I) -> Self
    where
        I: IntoIterator<Item = T>,
        T: Into<Server>,
    {
        self.servers.extend(servers.into_iter().map(Into::into));
        self
    }

    /// Run a hook over the finished document before it is written.
    ///
    /// This is the contract-time replacement for `App::document`: hooks that affect the document
    /// itself run here, not at runtime.
    pub fn document<F>(mut self, hook: F) -> Self
    where
        F: Fn(&mut OpenApi) + Send + Sync + 'static,
    {
        self.document_hooks.push(Box::new(hook));
        self
    }

    /// Record a documented layer guarantee for every operation below the app.
    pub fn layer_doc(mut self, doc: fn() -> LayerDoc) -> Self {
        self.layer_docs.push(doc);
        self
    }

    /// Add or suppress extractor rejection responses (`Auto` by default).
    pub fn document_rejections(mut self, mode: impl Into<DocumentRejections>) -> Self {
        self.document_rejections = mode.into();
        self
    }

    /// Keep strict builds. This is the default.
    pub fn strict(mut self) -> Self {
        self.strict = true;
        self
    }

    /// Downgrade build diagnostics to warnings.
    pub fn permissive(mut self) -> Self {
        self.strict = false;
        self
    }

    /// Allow operations without a documented success response.
    ///
    /// A permissive build uses this to publish a `default` placeholder, marked
    /// `x-roundhouse-unverified-response`. The strict pass does not set it.
    pub fn allow_undeclared_success(mut self, allow: bool) -> Self {
        self.allow_undeclared_success = allow;
        self
    }

    /// Register a response/body type's schema before the document is built.
    ///
    /// This is for private response bodies or bodies that do not otherwise appear in an extractor
    /// or return type, so the contract harness cannot name them.
    pub fn register<T: crate::doc::ApiSchema>(mut self) -> Self {
        self.registrations
            .push(<T as crate::doc::ApiSchema>::register);
        self
    }

    /// Set shared response prose defaults by status.
    ///
    /// A default replaces a response's canonical description. Explicit handler prose and a body
    /// type's description take priority. Use `0` for OpenAPI's `default` response.
    pub fn response_defaults(mut self, defaults: &[(u16, &'static str)]) -> Self {
        self.response_defaults.extend(
            defaults
                .iter()
                .map(|(status, text)| (*status, (*text).to_string())),
        );
        self
    }

    /// Resolve the route tree and build the contract.
    pub fn build(self) -> Result<BuiltContract, BuildError> {
        let mut diagnostics: Vec<Diagnostic> = Vec::new();
        let resolved = resolve_tree(
            &self.roots,
            self.strict,
            &self.layer_docs,
            Some(TypeId::of::<S>()),
            std::any::type_name::<S>(),
            0,
            &mut diagnostics,
        )?;

        let (document, mut observations) = build_openapi(
            self.info,
            &resolved,
            DocumentConfig {
                include_rejections: self.document_rejections == DocumentRejections::Auto,
                strict: self.strict,
                allow_undeclared_success: self.allow_undeclared_success,
                response_defaults: &self.response_defaults,
                registrations: &self.registrations,
                servers: &self.servers,
                hooks: &self.document_hooks,
            },
        )?;
        diagnostics.append(&mut observations.diagnostics);

        Ok(BuiltContract {
            document,
            routes: resolved,
            diagnostics,
            observations,
        })
    }
}

/// A generated contract plus the resolved routes and diagnostics that produced it.
pub struct BuiltContract {
    document: OpenApi,
    routes: Vec<ResolvedRoute>,
    diagnostics: Vec<Diagnostic>,
    observations: Observations,
}

impl BuiltContract {
    /// The generated OpenAPI document.
    pub fn document(&self) -> &OpenApi {
        &self.document
    }

    /// The resolved route table, sorted by path then method.
    pub fn routes(&self) -> &[ResolvedRoute] {
        &self.routes
    }

    /// Non-fatal observations collected while resolving and documenting the routes.
    pub fn diagnostics(&self) -> &[Diagnostic] {
        &self.diagnostics
    }

    /// The OpenAPI document as pretty JSON.
    pub fn openapi_json(&self) -> String {
        let mut value =
            serde_json::to_value(self.document.as_utoipa()).expect("OpenAPI document serializes");
        patch_encoding_headers(&mut value);
        serde_json::to_string_pretty(&value).expect("OpenAPI document serializes")
    }

    /// The runtime contract manifest as pretty JSON.
    ///
    /// This is deliberately a separate artifact from the OpenAPI document. It is the stable
    /// operation-keyed view the runtime will consume in the next phase.
    pub fn contract_json(&self) -> Result<String, serde_json::Error> {
        let document = serde_json::to_value(self.document.as_utoipa())?;
        let defs = self
            .document
            .as_utoipa()
            .components
            .as_ref()
            .map(|components| serde_json::to_value(&components.schemas))
            .transpose()?
            .unwrap_or_else(|| Value::Object(Map::new()));
        let mut body_ops = Map::new();
        let mut body_types = Map::new();
        let mut part_types = Map::new();

        for (name, schema) in &self.observations.bodies_named {
            body_types.insert(name.clone(), serde_json::to_value(schema)?);
        }
        for (name, schema) in &self.observations.parts_named {
            part_types.insert(name.clone(), serde_json::to_value(schema)?);
        }

        let mut operations = Vec::with_capacity(self.routes.len());
        for route in &self.routes {
            let source = route.record.source_ref();
            let body = self
                .observations
                .route_body_names
                .get(&route.operation_id)
                .and_then(|(type_name, content_type)| {
                    self.observations.bodies_named.get(type_name).map(|schema| {
                        (
                            content_type.clone(),
                            serde_json::to_value(schema).expect("schema serializes"),
                        )
                    })
                });
            if let Some((content_type, schema)) = &body {
                body_ops.insert(
                    route.operation_id.clone(),
                    json!({
                        "content_type": content_type,
                        "schema": schema,
                    }),
                );
            }
            let responses = contract_responses(&document, route);

            operations.push(json!({
                "operation_id": route.operation_id,
                "handler": route.record.handler_name,
                "method": route.method.as_str(),
                "path": route.path,
                "module": route.module_path,
                "source": {
                    "module": source.module_path,
                    "file": source.file,
                    "line": source.line,
                },
                "tags": route.tags,
                "deprecated": route.record.deprecated,
                "hidden": route.hidden || route.record.hidden,
                "security": route.auth.iter().map(|guard| guard.name).collect::<Vec<_>>(),
                "validation": match route.record.validation() {
                    ValidationPolicy::Schema => "schema",
                    ValidationPolicy::PartsOnly => "parts",
                    ValidationPolicy::Off => "off",
                },
                "request": {
                    "body": body.map(|(content_type, schema)| json!({
                        "content_type": content_type,
                        "schema": schema,
                    })),
                },
                "responses": responses,
            }));
        }

        let diagnostics: Vec<Value> = self
            .diagnostics
            .iter()
            .map(|diagnostic| {
                json!({
                    "message": diagnostic.message,
                    "source": {
                        "module": diagnostic.source.module_path,
                        "file": diagnostic.source.file,
                        "line": diagnostic.source.line,
                    },
                })
            })
            .collect();

        let contract = json!({
            "kind": "roundhouse.contract",
            "contract_version": 1,
            "generator_version": env!("CARGO_PKG_VERSION"),
            "openapi": "openapi.json",
            "operations": operations,
            "validation": {
                "defs": defs,
                "bodies": {
                    "ops": body_ops,
                    "types": body_types,
                },
                "parts": {
                    "types": part_types,
                },
            },
            "diagnostics": diagnostics,
        });

        serde_json::to_string_pretty(&contract)
    }

    /// Write `contract.json` and `openapi.json` into `directory`.
    pub fn write_to(&self, directory: impl AsRef<Path>) -> std::io::Result<()> {
        let directory = directory.as_ref();
        std::fs::create_dir_all(directory)?;
        let contract = self.contract_json().map_err(std::io::Error::other)?;
        std::fs::write(directory.join("contract.json"), format!("{contract}\n"))?;
        std::fs::write(
            directory.join("openapi.json"),
            format!("{}\n", self.openapi_json()),
        )?;
        Ok(())
    }
}

fn contract_responses(document: &Value, route: &ResolvedRoute) -> Vec<Value> {
    let method = route.method.as_str().to_ascii_lowercase();
    let Some(responses) =
        document["paths"][route.path.as_str()][method.as_str()]["responses"].as_object()
    else {
        return Vec::new();
    };
    responses
        .iter()
        .map(|(status, response)| {
            let status_number = if status == "default" {
                0
            } else {
                status.parse::<u16>().unwrap_or(0)
            };
            let mut object = response.as_object().cloned().unwrap_or_default();
            object.insert("status".to_string(), json!(status_number));
            Value::Object(object)
        })
        .collect()
}

/// Make `encoding` objects round-trip through utoipa's deserializer.
///
/// utoipa serializes an empty `headers` map by omitting it, but its `Encoding` type requires the
/// key when deserializing (there is no `#[serde(default)]`). The empty map is valid OpenAPI and
/// keeps `Built::document()` usable for multipart operations.
fn patch_encoding_headers(value: &mut Value) {
    match value {
        Value::Object(map) => {
            if let Some(Value::Object(encodings)) = map.get_mut("encoding") {
                for encoding in encodings.values_mut() {
                    if let Value::Object(encoding) = encoding {
                        encoding
                            .entry("headers".to_string())
                            .or_insert_with(|| Value::Object(Map::new()));
                    }
                }
            }
            for child in map.values_mut() {
                patch_encoding_headers(child);
            }
        }
        Value::Array(items) => {
            for item in items {
                patch_encoding_headers(item);
            }
        }
        _ => {}
    }
}
